import { Skeleton } from "@semec/ds-react";

<Skeleton className="h-4 w-[250px]" />
<Skeleton className="h-4 w-[180px]" />

import { EmptyState, Button } from "@semec/ds-react";
import { Inbox } from "lucide-react";

<EmptyState
  icon={<Inbox />}
  title="Nenhum protocolo encontrado"
  description="Ajuste os filtros ou abra um novo requerimento."
  action={<Button>Abrir requerimento</Button>}
/>

import { Breadcrumb } from "@semec/ds-react";

<Breadcrumb items={[
  { label: "Início", href: "/" },
  { label: "Serviços", href: "/servicos" },
  { label: "IPTU" },
]} />

import { ToastProvider, ToastViewport, useToast } from "@semec/ds-react";

function Acao() {
  const { toast } = useToast();
  return <Button onClick={() => toast({ variant: "success", title: "Protocolo enviado" })}>Enviar</Button>;
}

